def git_blob_sha(path: Path) -> str:
    data = path.read_bytes()
    header = f"blob {len(data)}\0".encode()
    return hashlib.sha1(header + data).hexdigest()


def require_baseline() -> None:
    for rel, expected in EXPECTED.items():
        path = ROOT / rel
        if not path.exists():
            raise SystemExit(f"missing locked target: {rel}")
        actual = git_blob_sha(path)
        if actual != expected:
            raise SystemExit(f"blob mismatch for {rel}: {actual} != {expected}")
    for rel in NEW_FILES:
        if (ROOT / rel).exists():
            raise SystemExit(f"new target already exists: {rel}")


def replace_once(rel: str, old: str, new: str) -> None:
    path = ROOT / rel
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"anchor count for {rel}: expected 1, got {count}\nANCHOR:\n{old[:500]}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8", newline="\n")


def write_new(rel: str, content: str) -> None:
    path = ROOT / rel
    if path.exists():
        raise SystemExit(f"refusing to overwrite new file: {rel}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")


